#include "physics.hpp"
#include <algorithm>
#include <chrono>
#include <cmath>
#include <iostream>
#include <set>
using namespace web;using namespace web::physics;
int main(){int failed=0;for(unsigned seed:{42u,99u})for(auto budget:{std::pair<int,int>{8,12}}){Recipe r;r.preset="corridor";r.seed=seed;r.density=.9;r.width=.0045;r.broken=0;r.quality=20;auto l=generate(r);BuildOptions o;o.massScale=.01;o.strength=1.25;o.stiffness=1;auto g=buildGraph(l,o);g.settings.substeps=budget.first;g.settings.iterations=budget.second;std::set<int> pinned;for(const auto&p:g.particles)if(p.anchor>=0)pinned.insert(p.component);std::vector<bool> supported;int unsupported=0;for(const auto&p:g.particles){supported.push_back(pinned.count(p.component));if(!supported.back())++unsupported;}const double e0=energy(g);double peak=e0,displacement=0,anchorDrift=0;std::string error;auto start=std::chrono::steady_clock::now();try{for(int t=0;t<10000;++t){step(g);peak=std::max(peak,energy(g));for(size_t i=0;i<g.particles.size();++i){const auto&p=g.particles[i];if(supported[i])displacement=std::max(displacement,length(p.x-p.rest));if(p.anchor>=0)anchorDrift=std::max(anchorDrift,length(p.x-p.rest));}if(!std::isfinite(peak))throw std::runtime_error("nonfinite energy");}}catch(const std::exception&e){error=e.what();}double finalSpeed=0,finalDisplacement=0;for(size_t i=0;i<g.particles.size();++i)if(supported[i]){finalSpeed=std::max(finalSpeed,length(g.particles[i].v));finalDisplacement=std::max(finalDisplacement,length(g.particles[i].x-g.particles[i].rest));}bool meshValid=true;try{auto view=bindView(l,g,0,128);meshValid=!view.mesh.faces.empty();for(auto face:view.mesh.faces){V3 a=view.mesh.vertices[face[0]].p,b=view.mesh.vertices[face[1]].p,c=view.mesh.vertices[face[2]].p;meshValid=meshValid&&std::isfinite(length(a))&&std::isfinite(length(b))&&std::isfinite(length(c))&&length(cross(b-a,c-a))>1e-12;}}catch(const std::exception&){meshValid=false;}const bool ok=error.empty()&&g.events.empty()&&peak<=e0*1.03&&anchorDrift==0&&unsupported==0&&finalSpeed<1e-7&&meshValid;failed+=!ok;std::cout<<(ok?"PASS":"FAIL")<<" seed="<<seed<<" substeps="<<budget.first<<" iterations="<<budget.second<<" particles="<<g.particles.size()<<" edges="<<g.edges.size()<<" unsupported_at_start="<<unsupported<<" initial_energy="<<e0<<" peak_energy="<<peak<<" peak_ratio="<<peak/e0<<" final_energy="<<energy(g)<<" max_supported_displacement="<<displacement<<" final_supported_displacement="<<finalDisplacement<<" final_max_speed="<<finalSpeed<<" anchor_drift="<<anchorDrift<<" breaks="<<g.events.size()<<" elapsed="<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<" error="<<error;for(const auto&e:g.events)std::cout<<" event("<<e.edge<<","<<e.cause<<","<<e.load<<")";std::cout<<std::endl;}return failed?1:0;}
